// C++ .cpg plug-in class implementing VGCore::IVGAppPlugin; m_pApp is a VGCore::IVGApplicationPtr (unverified)
HRESULT OnLoad(VGCore::IVGApplication *pApp) { m_pApp = pApp; return S_OK; }
HRESULT StartSession() { m_pApp->AddPluginCommand(L"MyTool.Run", L"Run My Tool", L"Runs my tool"); return S_OK; }
HRESULT StopSession() { m_pApp->RemovePluginCommand(L"MyTool.Run"); return S_OK; }
HRESULT OnUnload() { m_pApp = NULL; return S_OK; }
